# Let me analyze the demo more carefully by computing differences

demo_in = [
    [8, 0, 0],
    [0, 8, 0],
    [0, 0, 0]
]
demo_out = [
    [0, 2, 2],
    [2, 0, 2],
    [2, 2, 2]
]

# Compute cell-by-cell differences
print("Demo input → output mapping:")
for i in range(3):
    for j in range(3):
        in_val = demo_in[i][j]
        out_val = demo_out[i][j]
        if in_val > 0:
            print(f"  {in_val} → {out_val} (change by {out_val - in_val})")
        else:
            print(f"  {in_val} → {out_val} (zero became {out_val})")

# Count unique mappings
mappings = {}
for i in range(3):
    for j in range(3):
        in_val = demo_in[i][j]
        out_val = demo_out[i][j]
        mappings[(in_val, out_val)] = mappings.get((in_val, out_val), 0) + 1
print("\nUnique mappings:", mappings)

